String saaf(String x) {
  if (x == null) return "";
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < x.length(); i++) {
    char ch = x.charAt(i);
    int cp = (int) ch;
    if (Character.getType(ch) == Character.FORMAT) continue;
    if (cp == 160 || cp == 8199 || cp == 8239) { sb.append(" "); continue; }
    sb.append(ch);
  }
  return sb.toString().trim();
}
